describe('Home Page Navigation via Logo', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should navigate to home page when logo is clicked', () => {
    // Verify logo is visible
    cy.get('[data-testid="logo"]').should('be.visible');
    cy.get('[data-testid="logo"]').should('contain', 'Company Name');

    // Click the logo
    cy.get('[data-testid="logo"]').click();

    // Verify navigation to home page
    cy.url().should('include', '/');
    cy.get('[data-testid="home-title"]').should('be.visible');
    cy.get('[data-testid="home-title"]').should('contain', 'Welcome to Company Name');

    // Verify home page content is displayed
    cy.get('[data-testid="welcome-message"]').should('be.visible');
    cy.get('[data-testid="welcome-message"]').should('contain', 'Welcome to our website');
  });

  it('should handle logo click when already on home page', () => {
    // Navigate to home page
    cy.visit('/');

    // Verify we are on home page
    cy.url().should('include', '/');

    // Click the logo
    cy.get('[data-testid="logo"]').click();

    // Verify navigation does not change
    cy.url().should('include', '/');

    // Verify home page content remains unchanged
    cy.get('[data-testid="home-title"]').should('be.visible');
    cy.get('[data-testid="home-title"]').should('contain', 'Welcome to Company Name');

    // Verify no navigation history is created
    cy.get('[data-testid="nav-history"]').should('not.exist');
  });
});
